// Reproduce the continuous pointer timings and match both starts with the
// exact same pre-pointer attachments seeded via ordinary GPU commands.
#define main original_gpu_main
#include "main.cpp"
#undef main

int main(int argc, char** argv) {
    try {
        if (argc != 6) throw std::invalid_argument("MODE SAVE_DEPTH IDLE_CYCLES OUT.json PACKETS.bin");
        const std::string mode = argv[1];
        if (mode != "continuous" && mode != "matched") throw std::invalid_argument("unknown seed mode");
        const bool save_depth = std::stoi(argv[2]) != 0;
        const auto idle = std::stoull(argv[3]);
        Simulation sim("");
        Renderer oracle;
        std::uint32_t sequence = 1;
        const auto start = sim.cycles;
        const auto ui_primitives = [] {
            std::vector<Primitive> result;
            result.push_back(Rect{{0, 0, 640, 480}, overlay_state({16, 24, 48}), 0});
            result.push_back(Rect{{0, 0, 640, 24}, overlay_state({40, 80, 160}), 0});
            result.push_back(Rect{{8, 32, 632, 440}, overlay_state({220, 220, 220}), 0});
            for (int row = 0; row < 32; ++row) {
                const int y = 36 + row * 12;
                if (row % 2) result.push_back(Rect{{10, y, 630, y + 12}, overlay_state({200, 200, 210}), 0});
                for (int word = 0; word < 4; ++word) {
                    const int x = 16 + word * 150 + (row * 7) % 30;
                    result.push_back(Rect{{x, y + 2, x + 40 + (row * 13 + word * 17) % 80, y + 10},
                                          overlay_state({20, 20, 20}), 0});
                }
            }
            result.push_back(Rect{{0, 448, 640, 480}, overlay_state({40, 80, 160}), 0});
            return result;
        };

        const auto render = [&](const Pass& pass) {
            const auto program = hw::compile_pass(pass, sequence);
            sequence = program.next_sequence;
            sim.render(program);
            oracle.render(pass, RenderMode::Monolithic);
            sim.compare(oracle);
        };
        std::vector<std::uint8_t> token(4);
        hw::write_u32(token, 0, 0xbe7c);
        const auto copy = [&](const hw::CopyCommand& command) {
            sim.send(hw::encode_packet(hw::Opcode::CopyRect, sequence++, hw::encode_copy_command(command)));
            (void)sim.command(hw::Opcode::Fence, sequence++, token);
        };
        const auto pointer = Rect{{300, 200, 306, 209}, overlay_state({255, 255, 255}), 0};
        Pass pass;
        pass.target = 1;
        if (mode == "continuous") {
            render(pass);  // Warm up with empty color/depth clear.
            render(pass);  // Same warm clear used in production benchmark.
            pass.color_load = LoadOp::Load;
            render(pass);
            pass.depth_load = LoadOp::Load;
            render(pass);
            hw::CopyCommand command;
            command.source = 0; command.target = 1;
            command.width = screen_width; command.height = screen_height;
            copy(command);
            oracle.copy_rect(0, 1, {0, 0}, {0, 0}, screen_width, screen_height, RenderMode::Monolithic);
            sim.compare(oracle);
            pass = Pass{};
            pass.target = 1;
            pass.primitives = ui_primitives();
            render(pass);
            if (!save_depth) {
                pass.color_load = LoadOp::Load;
                pass.depth_load = LoadOp::Load;
                pass.primitives = {pointer};
                render(pass);
                pass = Pass{};
                pass.target = 1;
                pass.depth_store = StoreOp::Discard;
                render(pass);
                pass.primitives = ui_primitives();
                render(pass);
            }
        } else {
            // Derive the production pre-pointer color via independent SRR.
            // The preceding UI clears D24 to the boot value and writes only RGB.
            Pass seed;
            seed.target = 1;
            if (!save_depth) seed.depth_store = StoreOp::Discard;
            seed.primitives = ui_primitives();
            oracle.render(seed, RenderMode::Monolithic);

            // Seed that exact screen through the supported heap-image path.
            // Transfers don't use the rectangle raster path in either model.
            const auto& color = oracle.color(1);
            std::vector<std::uint8_t> image(color.size() * 2);
            for (std::size_t pixel = 0; pixel < color.size(); ++pixel)
                hw::write_u16(image, pixel * 2, color[pixel]);
            constexpr auto seed_base = hw::heap_base;
            for (std::size_t cursor = 0; cursor < image.size(); cursor += hw::maximum_upload_decoded_bytes) {
                const auto count = std::min(hw::maximum_upload_decoded_bytes, image.size() - cursor);
                const std::vector<std::uint8_t> chunk(image.begin() + static_cast<std::ptrdiff_t>(cursor),
                    image.begin() + static_cast<std::ptrdiff_t>(cursor + count));
                sim.send(hw::encode_packet(hw::Opcode::WriteHeap, sequence++,
                    hw::encode_heap_upload(seed_base + static_cast<std::uint32_t>(cursor), chunk)));
            }
            hw::CopyCommand command;
            command.image_source = true;
            command.target = 1;
            command.width = screen_width; command.height = screen_height;
            command.image = {seed_base, screen_width, screen_height, screen_width * 2};
            copy(command);
            sim.compare(oracle);
            // Match depth validity after the preceding full UI. Preserve RGB via LOAD.
            pass.color_load = LoadOp::Load;
            if (!save_depth) pass.depth_store = StoreOp::Discard;
            render(pass);
        }
        const auto seed_cycles = sim.cycles - start;
        for (std::uint64_t n = 0; n < idle; ++n) sim.tick();

        pass.color_load = LoadOp::Load;
        pass.depth_load = save_depth ? LoadOp::Load : LoadOp::Clear;
        pass.depth_store = save_depth ? StoreOp::Store : StoreOp::Discard;
        pass.primitives = {pointer};
        const auto program = hw::compile_pass(pass, sequence);
        const auto initial_cycle = sim.cycles;
        const auto initial_x = sim.dut.video_x, initial_y = sim.dut.video_y;
        const auto initial_memory = sim.memory.statistics();
        const auto initial_memory_state = sim.dut.rootp->nano_gpu_core__DOT__memory_service__DOT__state;
        const auto initial_refresh_age = sim.dut.rootp->nano_gpu_core__DOT__memory_service__DOT__refresh_age;
        const auto initial_bank_open = sim.dut.rootp->nano_gpu_core__DOT__memory_service__DOT__bank_open;
        const auto initial_color_hash = hash_string(oracle.color(1));
        sim.profiling = true;
        sim.render(program);
        sim.profiling = false;
        const auto final_memory = sim.memory.statistics();
        oracle.render(pass, RenderMode::Monolithic);
        sim.compare(oracle);
        const auto underflows = sim.scanout_underflows();
        if (underflows) throw std::runtime_error("pointer replay had scanout underflow");
        std::ofstream packets(argv[5], std::ios::binary);
        packets.write(reinterpret_cast<const char*>(program.bytes.data()), program.bytes.size());
        packets.close();
        if (!packets) throw std::runtime_error("cannot write timed pointer packet stream");
        std::ofstream out(argv[4]);
        out << "{\"mode\":\"" << mode << "\",\"save_depth\":" << (save_depth ? "true" : "false")
            << ",\"idle_cycles\":" << idle << ",\"seed_cycles\":" << seed_cycles
            << ",\"initial_core_cycle\":" << initial_cycle
            << ",\"initial_video_x\":" << unsigned(initial_x)
            << ",\"initial_video_y\":" << unsigned(initial_y)
            << ",\"initial_memory_state\":" << unsigned(initial_memory_state)
            << ",\"initial_refresh_age\":" << unsigned(initial_refresh_age)
            << ",\"initial_bank_open\":" << unsigned(initial_bank_open)
            << ",\"initial_sdram_refreshes\":" << initial_memory.refreshes
            << ",\"initial_sdram_reads\":" << initial_memory.read_commands
            << ",\"initial_sdram_writes\":" << initial_memory.write_commands
            << ",\"initial_framebuffer_fnv1a64\":\"" << initial_color_hash << '"'
            << ",\"first_sequence\":" << sequence << ",\"submitted_bytes\":" << program.bytes.size()
            << ",\"core_cycles\":" << sim.last_submission_cycles
            << ",\"raster_covered_cycles\":" << sim.raster_cycles[0]
            << ",\"load_command_cycles\":" << sim.core_states[21]
            << ",\"load_response_cycles\":" << sim.core_states[22]
            << ",\"store_command_cycles\":" << sim.core_states[36]
            << ",\"store_response_cycles\":" << sim.core_states[42]
            << ",\"sdram_read_commands\":" << final_memory.read_commands - initial_memory.read_commands
            << ",\"sdram_refreshes\":" << final_memory.refreshes - initial_memory.refreshes
            << ",\"oracle_checked\":true,\"scanout_underflows\":" << underflows << "}\n";
        out.close();
        if (!out) throw std::runtime_error("cannot write pointer result");
        std::cout << mode << " save_depth=" << save_depth << " idle=" << idle << " start="
                  << initial_cycle << " cycles=" << sim.last_submission_cycles << '\n';
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
